import java.util.Scanner;

/**
 * Variant 3: Using Scanner, minimal structure, direct output
 */
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        if (n > 11) {
            System.out.println("0");
            return;
        }
        int[] indices = new int[n];
        Point[] pts = new Point[n];
        for (int i = 0; i < n; i++) {
            int v = sc.nextInt(), w = sc.nextInt(), x = sc.nextInt(), y = sc.nextInt(), z = sc.nextInt();
            pts[i] = new Point(v, w, x, y, z);
        }

        StringBuilder result = new StringBuilder();
        int count = 0;
        for (int i = 0; i < n; i++) {
            boolean good = true;
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    if (i != j && i != k && j != k) {
                        Point one = pts[j];
                        Point two = pts[k];
                        Point three = pts[i];
                        Point lol2 = new Point(one.v - three.v, one.w - three.w, one.x - three.x, one.y - three.y, one.z - three.z);
                        Point lol1 = new Point(two.v - three.v, two.w - three.w, two.x - three.x, two.y - three.y, two.z - three.z);
                        if (angle(lol1, lol2)) {
                            good = false;
                        }
                    }
                }
            }
            if (good) {
                count++;
                result.append(i + 1).append("\n");
            }
        }
        if (count == 0) {
            System.out.println(0);
        } else {
            System.out.println(count);
            System.out.print(result.toString());
        }
    }

    static boolean angle(Point a, Point b) {
        double amag = a.mag();
        double bmag = b.mag();
        double dot = a.v * b.v + a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;
        return Math.toDegrees(Math.acos(dot / (amag * bmag))) < 90;
    }

    static class Point {
        int v, w, x, y, z;
        Point(int v, int w, int x, int y, int z) {
            this.v = v; this.w = w; this.x = x; this.y = y; this.z = z;
        }
        double mag() {
            return Math.sqrt(v * v + w * w + x * x + y * y + z * z);
        }
    }
}
